/* Merges window.NEWS_AUTO into window.MARKET_DATA in place, de-duplicating by url/title.
 * Call this AFTER xauusd-data.js and news-auto.js are both loaded, BEFORE app.js reads D.
 * Curated (hand-written) rows always sort first; auto rows are appended and flagged auto:true
 * so index.html/app.js can badge them differently if desired. */
window.mergeNewsAuto = function () {
  var D = window.MARKET_DATA, A = window.NEWS_AUTO;
  if (!D || !A) return;
  function dedupe(list, extra, key) {
    var seen = {}; (list || []).forEach(function (x) { seen[x[key]] = 1; });
    return (list || []).concat((extra || []).filter(function (x) { return x[key] && !seen[x[key]]; }));
  }
  D.incoming = dedupe(D.incoming, A.incoming, "event");
  (D.tabs || []).forEach(function (T) {
    var by = A.byTab[T.id]; if (!by) return;
    T.news = dedupe(T.news, by.news, "title");
    T.speakers = dedupe(T.speakers, by.speakers, "quote");
  });
};
if (window.MARKET_DATA) window.mergeNewsAuto();
